// CartPage.js
import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
  Container,
  Typography,
  Button,
  Box
} from '@mui/material';
import { removeFromCart, updateQuantity } from '../features/cartSlice';
import './CartPage.css';
import { useNavigate } from 'react-router-dom';  // Add this import at the top

const CartPage = () => {
  const cartItems = useSelector(state => state.cart.items);
  const total = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const dispatch = useDispatch();
  const navigate = useNavigate();  // Add this hook

  const handleQuantityChange = (id, delta) => {
    const item = cartItems.find(item => item.id === id);
    if (item) {
      const newQuantity = item.quantity + delta;
      if (newQuantity > 0) {
        dispatch(updateQuantity({ id, quantity: newQuantity }));
      }
    }
  };

  const handleRemove = id => {
    dispatch(removeFromCart(id));
  };

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" gutterBottom>Your Cart</Typography>
        {cartItems.length === 0 ? (
          <Typography variant="body1">Your cart is empty.</Typography>
        ) : (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {cartItems.map(item => (
              <Box key={item.id} sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', p: 2, border: '1px solid #ddd', borderRadius: 1 }}>
                <Typography variant="h6">{item.name}</Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                  <Button 
                    size="small" 
                    variant="outlined"
                    onClick={() => handleQuantityChange(item.id, -1)}
                  >-</Button>
                  <Typography>{item.quantity}</Typography>
                  <Button 
                    size="small" 
                    variant="outlined"
                    onClick={() => handleQuantityChange(item.id, 1)}
                  >+</Button>
                </Box>
                <Typography variant="h6">${(item.price * item.quantity).toFixed(2)}</Typography>
                <Button 
                  variant="contained" 
                  color="error"
                  onClick={() => handleRemove(item.id)}
                >
                  Remove
                </Button>
              </Box>
            ))}
          </Box>
        )}
      </Box>
      
      <Box sx={{ mt: 4, p: 3, bgcolor: 'background.paper', borderRadius: 1 }}>
        <Typography variant="h5" gutterBottom>Order Summary</Typography>
        {cartItems.map(item => (
          <Box key={item.id} sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
            <Typography>
              {item.name} x {item.quantity}
            </Typography>
            <Typography>
              ${(item.price * item.quantity).toFixed(2)}
            </Typography>
          </Box>
        ))}
        
        <Box sx={{ mt: 2, pt: 2, borderTop: '1px solid #ddd' }}>
          <Typography variant="h6" sx={{ display: 'flex', justifyContent: 'space-between' }}>
            <span>Total:</span>
            <span>${total.toFixed(2)}</span>
          </Typography>
        </Box>

        <Button 
          variant="contained" 
          color="primary"
          fullWidth
          sx={{ mt: 2 }}
          disabled={cartItems.length === 0}
          onClick={() => navigate('/checkout')}
        >
          Proceed to Checkout
        </Button>
      </Box>
    </Container>
  );
};

// Remove duplicate function definitions here
export default CartPage;
